INSERT INTO `products` (`id`, `code`, `brand_id`, `material_id`, `price`, `description`, `created_at`, `updated_at`) VALUES
(1, 'PM00014', 21, 4, 0.00, 'test', '2025-05-01 11:32:57', '2025-05-01 12:06:06'),
(2, 'PM00001', 4, 1, 1966.00, 'Plastové krytyod firmykrytypodmotor.czjsou vyráběny z materiálů nejvyšší jakosti s maximální přesností, tak aby zajistili tu nejlepší ochranu motoru. Všechny kryty jsou vyrobeny pomocí přesného zaměření podvozku daného vozidla. Každý kryt je důkladně otestován na vozidle tak, aby byla jeho montáž co nejjednodušší. Použitím plastového krytu pod motor se snižuje riziko koroze v motorové části na minimum. Kryt pod motor splňuje správnou funkčnost, chrání Váš motor co nejefektivněji a ušetří Vaší kapse na opravách motorových dílů. Montážní materiál není součástí balení krytu pod motor. .', '2025-05-01 11:57:20', '2025-05-01 11:57:20'),
